<?php

declare (strict_types=1);
namespace CresenityDevCloudAPMVendor\OpenTelemetry\SDK\Resource\Detectors;

use CresenityDevCloudAPMVendor\OpenTelemetry\SDK\Common\Attribute\Attributes;
use CresenityDevCloudAPMVendor\OpenTelemetry\SDK\Resource\ResourceDetectorInterface;
use CresenityDevCloudAPMVendor\OpenTelemetry\SDK\Resource\ResourceInfo;
use CresenityDevCloudAPMVendor\OpenTelemetry\SemConv\Incubating\Attributes\ServiceIncubatingAttributes;
use CresenityDevCloudAPMVendor\OpenTelemetry\SemConv\Version;
use CresenityDevCloudAPMVendor\Ramsey\Uuid\Uuid;
/**
 * @see https://github.com/open-telemetry/semantic-conventions/tree/main/docs/resource#service-experimental
 *
 * Spec deviation: Service Instance ID is not generated by the Service detector, as UUID is not useful in shared-nothing
 * PHP setups (FPM, Apache), and cannot be replaced by a more useful value due to Service being the last detector.
 */
final class ServiceInstance implements ResourceDetectorInterface
{
    #[\Override]
    public function getResource(): ResourceInfo
    {
        static $serviceInstanceId;
        $serviceInstanceId ??= Uuid::uuid4()->toString();
        $attributes = [ServiceIncubatingAttributes::SERVICE_INSTANCE_ID => $serviceInstanceId];
        return ResourceInfo::create(Attributes::create($attributes), Version::VERSION_1_38_0->url());
    }
}
